rap>									<?php  echo $r->Numero ?>							</td>							<td class="<?php echo $class?>">								<?php  echo $r->Nombre ?>							</td>							<td class="<?php echo $class?>" align="left">								<?php  echo $r->Descripcion ?>							</td>							<td class="<?php echo $class?>" align="center">								<?php echo get_field("Linea","Nombre","IDLinea",$r->IDLinea);?>							</td>						</tr>												<tr>							<td  class="<?php echo $class?>" colspan="4" nowrap align="left"><b>TALLAS</b><br>								<?php 								if(db_num_rows( $query_tallas ) > 0)								{								?>										<table width=90% align=center>										<tr>											<?php 												$numcols = 6;												$contador = 1;												while( $r_tallas = db_fetch_object( $query_tallas ) )												{																										if( $r_tallas->Existencias > 0 || $modulo=="movimiento" )													{														echo "<td>";														if( $r_tallas->Existencias > 0 || $modulo=="movimiento" )														{															$talla = get_field( "Talla","Descripcion","IDTalla",$r_tallas->IDTalla );																														/**********Consulta de Valor de la Referencia***********/																														$Precio = get_field("Precio","ValorVenta","IDPrecio",$r->IDPrecio);															$Descuento = get_field("Precio","Descuento","IDPrecio",$r->IDPrecio);																														if( ( ($Descuento <> "") && ($Descuento <> 0) ) )																$ValorUnitario = $Precio - ( $Precio * ( $Descuento/100 ) );															else																$ValorUnitario = $Precio;																														/********Fin Consulta de Valor de la Referencia*********/																														echo "<a href=\"javascript:window.opener.selreferenciac('".$r->Numero."','".$r->Nombre."','".$talla."','".$r_tallas->IDCodificacionEspecifica."','".$cont."','".$r_tallas->Existencias."','".$ValorUnitario."');javascript:window.close()\">";																												}//end if( $r_tallas->Existencias > 0 )																													echo get_field("Talla","Descripcion","IDTalla",$r_tallas->IDTalla);																												if( $r_tallas->Existencias > 0 || $modulo=="movimiento" )															echo "</a>";																																									if( $contador % $numcols == 0 )														{																													echo "</tr><tr>";															$contador = 0;																													}//end if( $contador % $numcols == 0 )																												$contador++;																												$disponibles = "SI";																										}//end if( $r_tallas->Existencias > 0 )																									}//end while( $r_tallas = db_fetch_object( $query_tallas ) )																								if($disponibles <> "SI")													echo "<td>NO HAY TALLAS DISPONIBLES</td>";											?>									</table>								<?php 								}								else									echo "NO HAY TALLAS DISPONIBLES";								?>							</td>						</tr>																		<?php 						} // END for						?>						<form action="<?php echo $PHP_SELF?>" method=get>							<tr>								<td class="rowtable" colspan="3" nowrap>Por										<select name="field">											<option selected value="Numero">Referencia</option>											<option value="Nombre">Nombre</option>										</select>									<input class="text" type="text" size="18" name="QryString">									<input type="hidden" name="action" value="list">									<input type="hidden" name="mod" value="busuario">									<input type="hidden" name="cont" value="<?php echo $cont?>">									<input type="hidden" name="IDPuntoVenta" value="<?php echo $IDPuntoVenta?>">
